# RWDM_SCALE1D: Scale1D: scale in one direction only. The script rwdm_scale1d_script.txt is generated by rwdm_gen.py (the closed forms are in that file); every case moves each Point object
# from its closed-form image E_k to the origin and lists it: the app prints a coordinate within 1e-9 of an integer as that integer, so a
# passing case means every image lies within 1e-9 of the textbook formula (a residual of 1e-6 would read 1e-06; RWDM_*_sensitivity checks that).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_SCALE1D_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_scale1d_script.txt" 2>&1)" || { echo "$RWDM_SCALE1D_OUT" | tail -40; echo "FAIL RWDM_SCALE1D_run: script exited non-zero"; fail=1; RWDM_SCALE1D_OUT=""; }
else
  RWDM_SCALE1D_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_scale1d_script.txt" 2>&1)" || { echo "$RWDM_SCALE1D_OUT" | tail -40; echo "FAIL RWDM_SCALE1D_run: script exited non-zero"; fail=1; RWDM_SCALE1D_OUT=""; }
fi
rwdm_scale1d_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_SCALE1D_OUT"; }
# rwdm_scale1d_check NAME N DESC: the case listed exactly N points and every one of them is "0,0,0" (the residual to the closed form)
rwdm_scale1d_check() {
  local blk npts zeros; blk="$(rwdm_scale1d_block "$1")"
  npts="$({ grep -cE '^history: Object [0-9]+ \(point\)' <<<"$blk" || true; })"
  zeros="$({ grep -cE '^history:   0,0,0$' <<<"$blk" || true; })"
  if [ "$npts" = "$2" ] && [ "$zeros" = "$2" ]; then echo "ok   RWDM_SCALE1D_$1: $3 ($2 points, every one within 1e-9 of the closed form)"
  else echo "FAIL RWDM_SCALE1D_$1: $3 (listed $npts points, $zeros at residual 0; expected $2 and $2)"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -12 | sed 's/^/     residual: /'; fi
}
rwdm_scale1d_check typedx 4 "Scale1D by 3 about (1,1,0) with a typed factor scales along the CPlane X axis only"
rwdm_scale1d_check refdir 4 "Scale1D by reference points along +y: origin (1,1,0), reference (1,3,0) (distance 2), new point (1,9,0) (distance 8): factor 4 in y only"
# negative control: the same harness must SEE a 1e-6 error (point moved 1e-6 off its expected image reads 1e-06, not 0)
rwdm_scale1d_sens() {
  local blk; blk="$(rwdm_scale1d_block sensitivity)"
  if grep -qE '^history:   (0,0,)?[-0-9.e]*1e-06' <<<"$blk" && ! grep -qE '^history:   0,0,0$' <<<"$blk"; then echo "ok   RWDM_SCALE1D_sensitivity: the residual harness reports a 1e-6 error as 1e-06 (negative control)"
  else echo "FAIL RWDM_SCALE1D_sensitivity: a 1e-6 error was not visible"; fail=1; { grep -E '^history:   ' <<<"$blk" || true; } | head -4 | sed 's/^/     residual: /'; fi
}
rwdm_scale1d_sens
